import{c as o,Q as t,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Session Insights — The Loop 唯一準則化 + Fable 5 世代改寫（九波 commits 全程）","description":"","frontmatter":{"title":"Session Insights — The Loop 唯一準則化 + Fable 5 世代改寫（九波 commits 全程）","date":"2026-06-11T00:00:00.000Z","status":"final","related":"2026-06-11-instruction-files-self-audit.md · loop-only-canon-integration.md · post-rewrite-self-audit.md · final-self-audit-v2.md","scope":"跨 17 小時、9+ commits、PR","type":"session-insights"},"headers":[],"relativePath":"research/reports/2026-06-11-session-insights-loop-fable-rewrite.md","filePath":"research/reports/2026-06-11-session-insights-loop-fable-rewrite.md","lastUpdated":1785909234000}'),i={name:"research/reports/2026-06-11-session-insights-loop-fable-rewrite.md"};function r(n,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="session-insights-—-2026-06-11" tabindex="-1">Session Insights — 2026-06-11 <a class="header-anchor" href="#session-insights-—-2026-06-11" aria-label="Permalink to &quot;Session Insights — 2026-06-11&quot;">​</a></h1><blockquote><p>本檔記<strong>可遷移的洞察</strong>（執行明細見 related 報告鏈）。每條格式：洞察 → 現場證據 → 落地位置。</p></blockquote><h2 id="_1-驗證閘門在最強模型世代「更」load-bearing-本-session-三次現場證明" tabindex="-1">1. 驗證閘門在最強模型世代「更」load-bearing（本 session 三次現場證明） <a class="header-anchor" href="#_1-驗證閘門在最強模型世代「更」load-bearing-本-session-三次現場證明" aria-label="Permalink to &quot;1. 驗證閘門在最強模型世代「更」load-bearing（本 session 三次現場證明）&quot;">​</a></h2><ul><li><strong>implementer 假成功</strong>：自報「verification all pass」，實際變更滯留未 commit 的 worktree——<code>git checkout &lt;branch&gt; -- &lt;path&gt;</code> 取回的是基底舊內容。</li><li><strong>auditor 訓練知識過期</strong>：fan-out researcher 斷言「Fable 5 為不存在模型」，而當下 session 即運行於 claude-fable-5。</li><li><strong>外部自動化「新標籤舊數據」</strong>：harness-model-fit.json 被改成 <code>model_version: claude-fable-5</code> 但 eval_baseline 仍是 sonnet 世代實測值——比 drift 更糟，因為它<strong>摧毀了 drift 偵測訊號本身</strong>。</li><li>與 papers 收斂：Vesper 強模型 eval-hack 16.6% vs 弱模型 0%。<strong>換更強模型該刪的是行為補丁，該留且該加固的是驗證閘門</strong>——這是整場「刪 14 條準則」工程的唯一裁決準星。</li><li>落地：core.md unverified_success 閘門原樣保留；fable-pilot「Frontier 驗證紀律」硬 gate；rejected-claims ledger 成為稽核協議標配。</li></ul><h2 id="_2-sub-agent-worktree-基底-工作分支-高破壞力陷阱" tabindex="-1">2. Sub-agent worktree 基底 ≠ 工作分支（高破壞力陷阱） <a class="header-anchor" href="#_2-sub-agent-worktree-基底-工作分支-高破壞力陷阱" aria-label="Permalink to &quot;2. Sub-agent worktree 基底 ≠ 工作分支（高破壞力陷阱）&quot;">​</a></h2><p>worktree 自動隔離的基底可能是 <strong>main 而非當前分支</strong> → 直接 cp 產出會<strong>回退本分支已套用的修正</strong>（本 session 實際洗掉 phase-1 順序修正，靠 diff --stat 驗證攔回）。防範三件套：① 產物指定寫 <code>/tmp/claude-scratch/</code>；② 取回後 <code>git diff</code> 驗「只含預期變更」；③ 重跑本分支已知 sweep。→ Lesson 2026-06-11-C + fable-pilot 硬 gate #2。</p><h2 id="_3-spend-limit-是一種-failure-mode-交接是一種能力" tabindex="-1">3. Spend limit 是一種 failure mode，交接是一種能力 <a class="header-anchor" href="#_3-spend-limit-是一種-failure-mode-交接是一種能力" aria-label="Permalink to &quot;3. Spend limit 是一種 failure mode，交接是一種能力&quot;">​</a></h2><p>org spend limit <strong>無預警終止</strong> background agent；但 agent 已分檔落盤 /tmp 的部分產出可由主對話驗收續用（pilot 三件套重寫因此零損失存活）。兩個推論：</p><ul><li><strong>委派長任務 = 要求 agent 每完成一檔即落盤</strong>，不等全部完成才輸出（Lesson 2026-06-11-D）。</li><li>交接不該是手工儀式 → 固化為 <code>/handoff</code> SKILL（hook 管遙測、SKILL 管內容；MEMORY 摘要必須自足，因 progress 檔 gitignored + 遠端容器 ephemeral）。</li></ul><h2 id="_4-動態數字寫進靜態文件-立即腐化-兩小時內實證兩次" tabindex="-1">4. 動態數字寫進靜態文件 = 立即腐化（兩小時內實證兩次） <a class="header-anchor" href="#_4-動態數字寫進靜態文件-立即腐化-兩小時內實證兩次" aria-label="Permalink to &quot;4. 動態數字寫進靜態文件 = 立即腐化（兩小時內實證兩次）&quot;">​</a></h2><p>auto-load byte 快照在本 session 內<strong>兩度手動同步、兩度再過期</strong>（18,969 → 18,985 → 18,986）。根治 = 刪數字、留命令指針（「跑 <code>measure.sh --gate</code>」）。一般化：<strong>SSoT 是量測命令，不是量測結果</strong>；任何「會動的值」入靜態文件前先問「誰負責讓它不過期？」答不出 → 寫命令不寫值。</p><h2 id="_5-半失效自動化比沉默更糟" tabindex="-1">5. 半失效自動化比沉默更糟 <a class="header-anchor" href="#_5-半失效自動化比沉默更糟" aria-label="Permalink to &quot;5. 半失效自動化比沉默更糟&quot;">​</a></h2><p><code>_sync_skill_roster.py</code> 每跑必印 <code>docs/INDEX.md: pattern not found</code> + exit 1——連本 session 主對話都兩次當雜訊忽略。半失效輸出<strong>訓練操作者跳過警告</strong>，腐蝕 Fail Loud 的可信度。判準：自動化的每行輸出都應 actionable；不可行動的警告 = 待修 bug 或待刪輸出。</p><h2 id="_6-「14-條-→-六階段」零損失移除的方法論" tabindex="-1">6. 「14 條 → 六階段」零損失移除的方法論 <a class="header-anchor" href="#_6-「14-條-→-六階段」零損失移除的方法論" aria-label="Permalink to &quot;6. 「14 條 → 六階段」零損失移除的方法論&quot;">​</a></h2><p>編號準則可以徹底退役而不損失行為契約，前提是三件事先成立：① 雙向對照表證明每條已被吸收（06-05/06-06 兩份報告交叉）；② 區分<strong>結構指針 vs 出處署名 vs 歷史記錄</strong>（指針改寫、署名保留、歷史不竄改）；③ 機械成功條件（活文件 grep = 0）。對照組教訓：harness-audit-METRICS 的 R1–R6 是<strong>自有命名空間</strong>——批次清除前必先分類命名空間，否則誤殺。</p><h2 id="_7-capability-conditioned-約束-強模型要目標不要步驟" tabindex="-1">7. Capability-conditioned 約束：強模型要目標不要步驟 <a class="header-anchor" href="#_7-capability-conditioned-約束-強模型要目標不要步驟" aria-label="Permalink to &quot;7. Capability-conditioned 約束：強模型要目標不要步驟&quot;">​</a></h2><p>Prompting Inversion（constrained CoT 在 frontier −2.36pp）+ 本 session 實感：對強模型，<strong>程序性約束是 token 稅兼 hyper-literalism 誘因</strong>（Think-Before hook 注入移除、200 行分段讀刪除），但<strong>目標表述 + 機械驗證條件</strong>反而要更強。新增約束前的自問句已入 fable-pilot IDENTIFY 行：「這會不會在已能正確推理的模型上誘發字面主義？」</p><h2 id="_8-byte-預算-99-9-使用率下的工程紀律" tabindex="-1">8. Byte 預算 99.9% 使用率下的工程紀律 <a class="header-anchor" href="#_8-byte-預算-99-9-使用率下的工程紀律" aria-label="Permalink to &quot;8. Byte 預算 99.9% 使用率下的工程紀律&quot;">​</a></h2><p>auto-load 終態 18,986/19,000（餘 14 bytes）。在硬頂附近運作的三條實戰法則：① <strong>增字先減字</strong>（每筆 CLAUDE.md/rules 編輯先算淨 byte）；② <strong>結構槓桿 &gt; 逐行刮</strong>（整段下沉 refs 一次回收數百 byte；逐行刪每輪 6–40 byte 還會誤削 mechanical check）；③ 上限的存在迫使「可推導 = 噪音」原則真正執行——預算壓力是規則庫品質的盟友。</p><h2 id="_9-模型分層的成本語義-使用者裁決後的定型" tabindex="-1">9. 模型分層的成本語義（使用者裁決後的定型） <a class="header-anchor" href="#_9-模型分層的成本語義-使用者裁決後的定型" aria-label="Permalink to &quot;9. 模型分層的成本語義（使用者裁決後的定型）&quot;">​</a></h2><p>日常預設 = Sonnet 4.6；Fable 5 = 重構/強化/優化/最強稽核<strong>場景觸發</strong>（新 session 切換）；Opus 4.8 = 審查 + cyber/bio 域（Fable silent fallback 防範）；Haiku = 搜尋/輕量。配套：<strong>Effort 先於 model</strong>（Fable medium ≈ Opus max；high 為甜蜜點）。「預設用最強」被否決的理由值得記：最強模型的正確用法是<strong>槓桿點投放</strong>，不是常駐。</p><h2 id="_10-雜項戰術教訓" tabindex="-1">10. 雜項戰術教訓 <a class="header-anchor" href="#_10-雜項戰術教訓" aria-label="Permalink to &quot;10. 雜項戰術教訓&quot;">​</a></h2><ul><li><code>cd /tmp &amp;&amp; bash scripts/x.sh</code> 複合命令讓相對路徑腳本炸掉（本 session 踩兩次）→ repo 腳本一律從 repo root 跑或改絕對路徑。</li><li>append-only jsonl 的 merge conflict 用 union 解（pre + ours + theirs-not-seen），勿擇邊。</li><li>squash merge 後 pinned 分支續用：<code>git merge origin/main</code>（非 rebase）+ jsonl union，分支即重新可用。</li><li>Ground-truth 注入應成為<strong>所有</strong>稽核類委派的標配段落：模型 roster、已修清單、「不存在類宣稱必先 ls」。</li></ul><h2 id="待續-交接" tabindex="-1">待續（交接） <a class="header-anchor" href="#待續-交接" aria-label="Permalink to &quot;待續（交接）&quot;">​</a></h2><ul><li>交叉驗證稽核（2 auditor）執行中——比對 final-self-audit-v2，產出附錄。</li><li>可選：<code>/harness-meta:hmf</code> 為 Fable 場景補測 baseline（model-fit <code>pending_revalidation</code> 已標）。</li></ul>',25)])])}const u=o(i,[["render",r]]);export{p as __pageData,u as default};
